-- =====================================================================
-- 고향으로 ON  데이터베이스 스키마 (PostgreSQL 15+ / PostGIS / pgvector)
--
-- 실행 방법
--   createdb hometown_on
--   psql -d hometown_on -f Crawling_Haman/Hometown_on.sql
-- (docker compose 로 띄운 경우 백엔드가 시작할 때 같은 스키마를 자동 생성합니다)
--
-- 이 파일은 HometownON/backend/app/models/models.py 와 1:1 로 일치해야 합니다. (테이블 34개)
-- 변환 메모 (MySQL → PostgreSQL)
--   AUTO_INCREMENT → GENERATED BY DEFAULT AS IDENTITY
--   ENUM(...)      → VARCHAR + CHECK 제약 (값 추가/삭제가 쉬움)
--   TINYINT        → SMALLINT,   MEDIUMTEXT → TEXT,   JSON → JSONB
--   TIMESTAMP      → TIMESTAMPTZ (시간대 포함)
--   ON UPDATE CURRENT_TIMESTAMP → set_updated_at() 트리거
--   POINT SRID 4326 → geometry(Point, 4326)  ※ 좌표 순서는 POINT(경도 위도)
--   ChromaDB      → rag_documents.embedding (pgvector)
-- =====================================================================

CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS vector;

-- updated_at 자동 갱신용 (MySQL 의 ON UPDATE CURRENT_TIMESTAMP 대체)
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- =====================================================================
-- 사람/계정/역량/배지
-- =====================================================================
CREATE TABLE users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email VARCHAR(255) CONSTRAINT uq_users_email UNIQUE,
  password_hash VARCHAR(255),
  phone VARCHAR(30),
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);
CREATE TRIGGER trg_users_updated_at BEFORE UPDATE ON users
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE user_profiles (
  user_id BIGINT PRIMARY KEY REFERENCES users(id),
  display_name VARCHAR(80),
  profile_image VARCHAR(500),
  birth_year SMALLINT,
  gender VARCHAR(6) CONSTRAINT ck_user_profiles_gender CHECK (gender IN ('male','female','other')),
  home_region VARCHAR(120),      -- 고향/귀향 지역(예: 경남 함안군)
  target_region VARCHAR(120),    -- 정착 희망 지역
  preferences JSONB,             -- 관심분야/선호 카테고리/가용시간 등
  bio TEXT,
  mentor_available BOOLEAN DEFAULT false,
  mentor_hourly_rate INTEGER
);

CREATE TABLE social_accounts (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  provider VARCHAR(6) NOT NULL CONSTRAINT ck_social_accounts_provider CHECK (provider IN ('google','kakao','naver','apple')),
  provider_uid VARCHAR(255) NOT NULL,
  CONSTRAINT uq_social_accounts_provider_uid UNIQUE (provider, provider_uid)
);
CREATE INDEX ix_social_accounts_user_id ON social_accounts (user_id);

CREATE TABLE skills (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code VARCHAR(64) CONSTRAINT uq_skills_code UNIQUE,
  name VARCHAR(120),
  category VARCHAR(80)           -- 예: IT, 농업, 돌봄, 교육 등
);

CREATE TABLE user_skills (
  user_id BIGINT REFERENCES users(id),
  skill_id BIGINT REFERENCES skills(id),
  level SMALLINT,                -- 1~5 등급
  certified BOOLEAN DEFAULT false,
  PRIMARY KEY (user_id, skill_id)
);

CREATE TABLE badges (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code VARCHAR(64) CONSTRAINT uq_badges_code UNIQUE,
  name VARCHAR(120),
  description TEXT
);

CREATE TABLE user_badges (
  user_id BIGINT REFERENCES users(id),
  badge_id BIGINT REFERENCES badges(id),
  awarded_at TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY (user_id, badge_id)
);

-- =====================================================================
-- 미션(추천/수행)
-- =====================================================================
CREATE TABLE missions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code VARCHAR(64) CONSTRAINT uq_missions_code UNIQUE,
  title VARCHAR(200),
  mission_type VARCHAR(5) NOT NULL CONSTRAINT ck_missions_mission_type CHECK (mission_type IN ('탐색형','사회유대형','커리어형')),
  difficulty SMALLINT DEFAULT 1,
  expected_minutes SMALLINT,
  tags JSONB,                    -- ["경로당","마을회관","문화체험"] 등
  description TEXT,
  thumbnail_image VARCHAR(500)
);

CREATE TABLE mission_parts (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  mission_id BIGINT NOT NULL REFERENCES missions(id),
  step_no SMALLINT NOT NULL,
  instruction TEXT,              -- 세부 단계 안내
  checklist JSONB,               -- 체크리스트(선택)
  CONSTRAINT uq_mission_parts_mission_step UNIQUE (mission_id, step_no)
);

-- 사용자에게 실제로 배정된 미션 인스턴스
CREATE TABLE mission_assignments (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  mission_id BIGINT NOT NULL REFERENCES missions(id),
  assigned_at TIMESTAMPTZ DEFAULT now(),
  due_date DATE,
  status VARCHAR(11) DEFAULT 'assigned' CONSTRAINT ck_mission_assignments_status CHECK (status IN ('assigned','in_progress','completed','skipped','canceled')),
  context JSONB                  -- 추천 근거(장소/문화/이전행동 등)
);
CREATE INDEX ix_mission_assignments_user_status ON mission_assignments (user_id, status);
CREATE INDEX ix_mission_assignments_mission_id ON mission_assignments (mission_id);

CREATE TABLE mission_progress (
  assignment_id BIGINT PRIMARY KEY REFERENCES mission_assignments(id),
  progress_pct SMALLINT DEFAULT 0,
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  feedback TEXT
);

CREATE TABLE mission_part_progress (
  assignment_id BIGINT REFERENCES mission_assignments(id),
  part_id BIGINT REFERENCES mission_parts(id),
  done BOOLEAN DEFAULT false,
  memo TEXT,
  done_at TIMESTAMPTZ,
  PRIMARY KEY (assignment_id, part_id)
);

-- =====================================================================
-- 지역 데이터(함안군 자료)
-- =====================================================================
-- 카테고리 사전(대/소분류)
CREATE TABLE location_categories (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  main VARCHAR(50),              -- 예: '식음료','의료','공공시설'
  sub VARCHAR(80),               -- 예: '맛집','카페','병원/의원','경로당','마을회관'
  CONSTRAINT uq_location_categories_main_sub UNIQUE (main, sub)
);

-- 공간 포인트 (PostGIS, WGS84)
CREATE TABLE locations (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(200) NOT NULL,
  category_id INTEGER NOT NULL REFERENCES location_categories(id),
  address VARCHAR(300) NOT NULL,
  phone VARCHAR(40),
  geom geometry(Point, 4326) NOT NULL,   -- POINT(경도 위도)
  extra JSONB                            -- 원시칼럼 보관(출처/링크 등)
);
CREATE INDEX ix_locations_geom ON locations USING gist (geom);
CREATE INDEX ix_locations_category_id ON locations (category_id);
CREATE INDEX ix_locations_name ON locations (name);

CREATE TABLE location_hours (
  location_id BIGINT REFERENCES locations(id),
  weekday SMALLINT,              -- 0(일)~6(토)
  open_time TIME,
  close_time TIME,
  is_24h BOOLEAN DEFAULT false,
  PRIMARY KEY (location_id, weekday)
);

CREATE TABLE location_tags (
  location_id BIGINT REFERENCES locations(id),
  tag VARCHAR(60),
  PRIMARY KEY (location_id, tag)
);
CREATE INDEX ix_location_tags_tag ON location_tags (tag);

-- 스토리성 텍스트(임베딩 대상)
CREATE TABLE culture (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  category VARCHAR(3) NOT NULL CONSTRAINT ck_culture_category CHECK (category IN ('인물','전설','유래','역사','문화재')),
  title VARCHAR(300) NOT NULL,
  story TEXT NOT NULL,
  haman_url VARCHAR(500),
  created_at TIMESTAMPTZ DEFAULT now()
);

-- =====================================================================
-- 상호작용/로그
-- =====================================================================
CREATE TABLE chat_sessions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT REFERENCES users(id),
  started_at TIMESTAMPTZ DEFAULT now(),
  session_data JSONB
);

CREATE TABLE chat_messages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id BIGINT NOT NULL REFERENCES chat_sessions(id),
  role VARCHAR(9) NOT NULL CONSTRAINT ck_chat_messages_role CHECK (role IN ('user','assistant','tool')),
  content TEXT NOT NULL,
  tokens INTEGER,
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX ix_chat_messages_session_created ON chat_messages (session_id, created_at);

CREATE TABLE activity_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT REFERENCES users(id),
  event_type VARCHAR(80) NOT NULL,    -- e.g., 'mission_completed','search','login'
  payload JSONB,
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX ix_activity_logs_event_created ON activity_logs (event_type, created_at);

CREATE TABLE location_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT REFERENCES users(id),
  geom geometry(Point, 4326) NOT NULL,
  recorded_at TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX ix_location_logs_geom ON location_logs USING gist (geom);
CREATE INDEX ix_location_logs_user_recorded ON location_logs (user_id, recorded_at);

-- =====================================================================
-- RAG/임베딩 (pgvector, 기존 ChromaDB 대체)
-- =====================================================================
CREATE TABLE data_sources (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(120) CONSTRAINT uq_data_sources_name UNIQUE,  -- 'haman_csv','haman_site','etc'
  description TEXT
);

-- 검색 대상 문서와 임베딩 벡터 (컬렉션 = 기존 Chroma 컬렉션)
--   haman_culture : culture 이야기
--   missions      : 미션 설명
-- 임베딩 모델은 .env 의 EMBEDDING_MODEL 하나로 통일 (현재 nvidia/nemotron-3-embed-1b:free, 2048차원).
-- 모델을 바꿔도 테이블을 고치지 않도록 차원 없는 vector 타입을 쓰고, 검색은 같은 컬렉션·같은 모델 벡터끼리만 합니다.
-- (데이터가 수천 건 수준이라 인덱스 없이 정확 검색. 인덱스가 필요해지면 2000차원 초과이므로 halfvec + HNSW)
CREATE TABLE rag_documents (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  collection_name VARCHAR(120) NOT NULL,
  source_table VARCHAR(9) NOT NULL CONSTRAINT ck_rag_documents_source_table CHECK (source_table IN ('culture','locations','missions')),
  source_id BIGINT NOT NULL,             -- 해당 테이블의 PK
  content TEXT NOT NULL,                 -- 임베딩한 원문
  doc_metadata JSONB,                    -- 제목/카테고리 등 표시용 정보
  embedding vector NOT NULL,
  embedding_model VARCHAR(160) NOT NULL, -- 사용 모델명
  created_at TIMESTAMPTZ DEFAULT now(),
  CONSTRAINT uq_rag_documents_source UNIQUE (collection_name, source_table, source_id)
);

-- =====================================================================
-- 커뮤니티 (프론트엔드 요구사항 반영)
-- =====================================================================
-- 1) 통합 게시판 (자유·의뢰·멘토)
--   category 는 앱 화면의 카테고리 키 (게시판별 허용 값은 백엔드 models.BOARD_CATEGORIES)
--     free   : daily, food, memory, nature, hobby, other
--     request: repair, agriculture, it, cleaning, installation
--     mentor : technical, agriculture, lifestyle, business, education, seeking, offering
--   attributes 는 게시판별 추가 정보
--     request: budget, location, deadline, required_skills
--     mentor : experience, hourly_rate, location, skills, preferred_method
CREATE TABLE board_posts (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  author_user_id BIGINT NOT NULL REFERENCES users(id),
  board_type VARCHAR(7) NOT NULL CONSTRAINT ck_board_posts_board_type CHECK (board_type IN ('free','request','mentor')),
  category VARCHAR(30) NOT NULL,
  title VARCHAR(200) NOT NULL,
  content TEXT NOT NULL,
  images JSONB,                          -- 첨부 이미지 URL 배열
  attributes JSONB,                      -- 게시판별 추가 정보 (예산, 시간당 요금 등)
  match_status VARCHAR(8) CONSTRAINT ck_board_posts_match_status CHECK (match_status IN ('open','matched','closed','canceled')),  -- 의뢰·멘토 글 진행 상태 (자유게시판은 NULL)
  views_count INTEGER DEFAULT 0,
  likes_count INTEGER DEFAULT 0,
  comments_count INTEGER DEFAULT 0,
  status VARCHAR(7) DEFAULT 'active' CONSTRAINT ck_board_posts_status CHECK (status IN ('active','hidden','deleted')),
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);
CREATE TRIGGER trg_board_posts_updated_at BEFORE UPDATE ON board_posts
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX ix_board_posts_board_category_created ON board_posts (board_type, category, created_at);
CREATE INDEX ix_board_posts_author_user_id ON board_posts (author_user_id);
CREATE INDEX ix_board_posts_board_match_status ON board_posts (board_type, match_status);

-- 1-1) 매칭 기록 (의뢰 수락, 멘토링 신청)
CREATE TABLE matches (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  post_id BIGINT NOT NULL REFERENCES board_posts(id),   -- 의뢰 또는 멘토 글
  user_id BIGINT NOT NULL REFERENCES users(id),         -- 수락하거나 신청한 사람
  status VARCHAR(9) DEFAULT 'proposed' CONSTRAINT ck_matches_status CHECK (status IN ('proposed','accepted','rejected','completed')),
  created_at TIMESTAMPTZ DEFAULT now(),
  CONSTRAINT uq_matches_post_user UNIQUE (post_id, user_id)
);
CREATE INDEX ix_matches_user_id ON matches (user_id);

-- 2) 게시글 댓글
CREATE TABLE board_comments (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  post_id BIGINT NOT NULL REFERENCES board_posts(id),
  author_user_id BIGINT NOT NULL REFERENCES users(id),
  content TEXT NOT NULL,
  parent_comment_id BIGINT REFERENCES board_comments(id),   -- 대댓글용
  likes_count INTEGER DEFAULT 0,
  status VARCHAR(7) DEFAULT 'active' CONSTRAINT ck_board_comments_status CHECK (status IN ('active','hidden','deleted')),
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX ix_board_comments_post_created ON board_comments (post_id, created_at);

-- 3) 좋아요 시스템
CREATE TABLE likes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  target_type VARCHAR(7) NOT NULL CONSTRAINT ck_likes_target_type CHECK (target_type IN ('post','comment')),
  target_id BIGINT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT now(),
  CONSTRAINT uq_likes_user_target UNIQUE (user_id, target_type, target_id)
);
CREATE INDEX ix_likes_target ON likes (target_type, target_id);

-- 4) 알림 시스템
CREATE TABLE notifications (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  type VARCHAR(16) NOT NULL CONSTRAINT ck_notifications_type CHECK (type IN ('mission_complete','badge_earned','mentor_match','request_match','comment','like','weather','system')),
  title VARCHAR(200) NOT NULL,
  message TEXT NOT NULL,
  data JSONB,                            -- 관련 데이터 (ID, URL 등)
  is_read BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX ix_notifications_user_read_created ON notifications (user_id, is_read, created_at);

-- 5) 1:1 메신저 시스템
CREATE TABLE conversations (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user1_id BIGINT NOT NULL REFERENCES users(id),
  user2_id BIGINT NOT NULL REFERENCES users(id),
  last_message_at TIMESTAMPTZ DEFAULT now(),
  user1_unread_count INTEGER DEFAULT 0,
  user2_unread_count INTEGER DEFAULT 0,
  status VARCHAR(7) DEFAULT 'active' CONSTRAINT ck_conversations_status CHECK (status IN ('active','blocked','deleted')),
  created_at TIMESTAMPTZ DEFAULT now(),
  CONSTRAINT uq_conversations_users UNIQUE (user1_id, user2_id)
);
CREATE INDEX ix_conversations_user1_last ON conversations (user1_id, last_message_at);
CREATE INDEX ix_conversations_user2_last ON conversations (user2_id, last_message_at);

CREATE TABLE conversation_messages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  conversation_id BIGINT NOT NULL REFERENCES conversations(id),
  sender_id BIGINT NOT NULL REFERENCES users(id),
  message_type VARCHAR(6) DEFAULT 'text' CONSTRAINT ck_conversation_messages_message_type CHECK (message_type IN ('text','image','file','system')),
  content TEXT NOT NULL,
  is_read BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX ix_conversation_messages_conv_created ON conversation_messages (conversation_id, created_at);

-- 6) 멘토 평가 시스템
CREATE TABLE mentor_reviews (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  mentor_user_id BIGINT NOT NULL REFERENCES users(id),
  reviewer_user_id BIGINT NOT NULL REFERENCES users(id),
  match_id BIGINT REFERENCES matches(id),   -- 어떤 매칭에서 나온 리뷰인지
  rating SMALLINT NOT NULL,                 -- 1-5점
  comment TEXT,
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX ix_mentor_reviews_mentor_rating ON mentor_reviews (mentor_user_id, rating);

-- 7) 사용자 목표 설정
CREATE TABLE user_goals (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  goal_type VARCHAR(23) NOT NULL CONSTRAINT ck_user_goals_goal_type CHECK (goal_type IN ('mission_count','skill_level','community_participation','mentor_sessions')),
  target_value INTEGER NOT NULL,
  current_value INTEGER DEFAULT 0,
  period VARCHAR(7) NOT NULL CONSTRAINT ck_user_goals_period CHECK (period IN ('daily','weekly','monthly','yearly')),
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  status VARCHAR(9) DEFAULT 'active' CONSTRAINT ck_user_goals_status CHECK (status IN ('active','completed','paused','canceled')),
  created_at TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX ix_user_goals_user_status ON user_goals (user_id, status);

-- 8) 날씨 정보 (캐시용)
CREATE TABLE weather_cache (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  region VARCHAR(100) NOT NULL,
  date DATE NOT NULL,
  temperature_min NUMERIC(4,1),
  temperature_max NUMERIC(4,1),
  weather_condition VARCHAR(50),
  description VARCHAR(200),
  updated_at TIMESTAMPTZ DEFAULT now(),
  CONSTRAINT uq_weather_cache_region_date UNIQUE (region, date)
);
CREATE TRIGGER trg_weather_cache_updated_at BEFORE UPDATE ON weather_cache
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 9) 앱 공지사항
CREATE TABLE announcements (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title VARCHAR(200) NOT NULL,
  content TEXT NOT NULL,
  type VARCHAR(11) NOT NULL CONSTRAINT ck_announcements_type CHECK (type IN ('notice','update','event','maintenance')),
  is_important BOOLEAN DEFAULT false,
  start_date TIMESTAMPTZ NOT NULL,
  end_date TIMESTAMPTZ,
  status VARCHAR(8) DEFAULT 'active' CONSTRAINT ck_announcements_status CHECK (status IN ('active','inactive')),
  created_at TIMESTAMPTZ DEFAULT now()
);

