-- 4) 전체 합계
-- SELECT (SELECT COUNT(*) FROM locations) AS locations_cnt,
--        (SELECT COUNT(*) FROM culture)   AS culture_cnt,
--        (SELECT COUNT(*) FROM rag_documents) AS embedded_docs;
